{"command":"python3 << 'EOF'
import csv

with open('outputs/t08_pois_clean.csv', 'r', newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    rows = list(reader)
    print(f"Read {len(rows)} rows")

    # Check all labels are non-empty
    for row in rows:
        if not row['label']:
            print(f"ERROR: Empty label for qid {row['qid']}")

    # Check coordinates are numeric
    for row in rows:
        lat = row['latitude']
        lon = row['longitude']
        try:
            lat_num = float(lat)
            lon_num = float(lon)
            if not (-90 <= lat_num <= 90) or not (-180 <= lon_num <= 180):
                print(f"ERROR: Invalid range for qid {row['qid']}: lat={lat_num}, lon={lon_num}")
        except ValueError:
            print(f"ERROR: Non-numeric coordinates for qid {row['qid']}: lat={lat}, lon={lon}")

print("Validation complete")
EOF"}
